/**
 * The addresses a link block may point to.
 *
 * @module      tiny_c4lauthor/webaddress
 * @copyright   2026 bdecent gmbh <https://bdecent.de>
 * @license     http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * Whether a value is an absolute web or mail address (http, https or mailto), the only
 * addresses a link block may point to.
 *
 * @param {string} value
 * @returns {boolean}
 */
export const isWebAddress = (value) => /^(https?:\/\/|mailto:)/i.test(value.trim());
